import {storyTrackCatalog,storyTrackKey} from '../../../domain/story-tracks.mjs';
import {planningCardPresentation} from '../../shared/planning-card-presentation.mjs';
import {Icon} from '../../shared/icons.tsx';
import {browserDraftStorage} from '../../shared/drafts.js';
import React,{useContext,useEffect,useLayoutEffect,useMemo,useRef,useState} from 'react';
import {SessionScope} from '../../shared/state.js';
import {pair} from '../../../domain/story-relations.mjs';
import {Modal} from '../../shared/preferences.tsx';
import {createStoryProjection,formatStoryDate} from '../../../domain/story-axis.mjs';
import {axisProjectionOptions,axisTicks,storyLaneLayout,storyDragDrop,storyDisplayCards,storyDefaultCursor,storyGapLabel,storyTickLabel,storyZoomLevels,storyCardRowHeight,storyCardHeight} from './story-axis-view.mjs';
import {StoryAxisSetup,StoryMarkerEditor,StoryPlacementEditor,StoryTrackEditor} from './StoryAxisPanels.jsx';
import {storyAxisStyle} from './story-axis-style.mjs';
import {TimelineRelations} from './TimelineRelations.jsx';
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function StoryTimeAxis({foreshadowIds=new Set(),editor=null,state,sources,people,save,unavailable,open,onCreate,onMore,relationClock,call,novelId,relations=[],evolution,onMemory,relationTarget,onRelationReady}){
 const sessionScope=useContext(SessionScope),intentKey=`cuigengji:story-axis-intent:${sessionScope}:${novelId}`;
 const [intent,setIntent]=useState(()=>{try{return JSON.parse(browserDraftStorage.getItem(intentKey)||'null');}catch{return null;}}),[intentError,setIntentError]=useState('');
 const axis=state.storyAxis,[panel,setPanel]=useState(null),[zoom,setZoom]=useState(0),[selected,setSelected]=useState(null),[drag,setDrag]=useState(null),[query,setQuery]=useState(''),[view,setView]=useState(relationTarget?'relations':'axis'),[storedCursor,setCursor]=useState(axis?.anchor.coordinate??null);
 const cursor=storyDefaultCursor(axis,storedCursor),catalog=storyTrackCatalog(axis,state.tracks||[]);
 const [trackFilter,setTrackFilter]=useState('all');
 const previousProjection=useRef(null),viewport=useRef(null),gesture=useRef(null),alive=useRef(true),dragged=useRef(false),locked=useRef(false),latest=useRef(null);
 useEffect(()=>{alive.current=true;return()=>{alive.current=false;gesture.current=null;};},[novelId]);
 useEffect(()=>{if(relationTarget){setView('relations');onRelationReady?.();}},[relationTarget]);
 const zoomLevels=axis?storyZoomLevels(axis):{overview:0,detail:5,daily:12},zoomPreset=zoom<=0?'overview':axis&&axisProjectionOptions(axis,zoom).windowDays<=3?'daily':'detail';
 const cards=Object.values(state.cards),placed=cards.filter(c=>c.time?.story?.axisVersion===1),pending=cards.filter(c=>c.time?.story?.axisVersion!==1);
 const projection=useMemo(()=>axis?createStoryProjection([axis.anchor.coordinate,...axis.markers.map(m=>m.coordinate),...placed.flatMap(c=>[c.time.story.start,c.time.story.end])],axisProjectionOptions(axis,zoom)):null,[axis,state.cards,zoom]);
 const visiblePlaced=trackFilter==='all'?placed:placed.filter(c=>storyTrackKey(c.time.story)===trackFilter);
 const displayCards=projection?storyDisplayCards(visiblePlaced,projection,axis,state.tracks):visiblePlaced;
 const baseLayout=axis?storyLaneLayout(axis,displayCards,state.tracks):null,ticks=axis?axisTicks(axis,projection,zoom):[];
 const markerRows=[],markers=axis?[...axis.markers].sort((a,b)=>a.coordinate-b.coordinate).map(marker=>{const x=projection.timeToX(marker.coordinate),width=Math.min(180,marker.label.length*12+32);let row=0;while(markerRows[row]!==undefined&&markerRows[row]>x-width/2-12)row++;markerRows[row]=x+width/2;return {...marker,displayRow:row};}):[];
 const markerSpace=markerRows.length?Math.max(12,(markerRows.length-1)*34+12):0,layout=baseLayout?{...baseLayout,height:baseLayout.height+markerSpace,lanes:baseLayout.lanes.map(l=>l.side==='below'?{...l,y:l.y+markerSpace}:l)}:null;
 latest.current={projection,layout,axis,unavailable};
 useLayoutEffect(()=>{const el=viewport.current,old=previousProjection.current;if(el&&old&&projection&&old!==projection){const point=old.xToTime(el.scrollLeft+el.clientWidth/2-64);el.scrollLeft=Math.max(0,projection.timeToX(point)+64-el.clientWidth/2);}previousProjection.current=projection;},[projection]);
 const focusCoordinate=n=>{if(!alive.current)return;setCursor(n);requestAnimationFrame(()=>{const el=viewport.current,p=latest.current?.projection;if(el&&p)el.scrollLeft=Math.max(0,p.timeToX(n)+64-el.clientWidth/2);});};
 useEffect(()=>{if(!axis)return;setCursor(axis.anchor.coordinate);const id=requestAnimationFrame(()=>{const el=viewport.current;if(el)el.scrollLeft=Math.max(0,projection.timeToX(axis.anchor.coordinate)+64-el.clientWidth/2);});return()=>cancelAnimationFrame(id);},[axis?.anchor.coordinate]);
 // Keep the mounted axis and relation graph positions when switching narrow-screen tabs.
 const cancel=()=>{gesture.current=null;setDrag(null);};
 useEffect(()=>{const key=e=>{if(e.key==='Escape')cancel();};window.addEventListener('blur',cancel);window.addEventListener('keydown',key);return()=>{window.removeEventListener('blur',cancel);window.removeEventListener('keydown',key);};},[]);
 const dispatch=async(request,message)=>{if(locked.current||!alive.current)return false;locked.current=true;try{const ok=await save(request.operation,message,request);if(ok||['CONFLICT','STORY_INVALID'].includes(save.failure?.code)){browserDraftStorage.removeItem(intentKey);if(alive.current)setIntent(null);}return ok;}finally{locked.current=false;}};
 const mutate=async(op,message)=>{if(intent||locked.current||!alive.current)return false;const request={novelId,requestId:crypto.randomUUID(),expectedRevision:state.revision,operation:op};try{browserDraftStorage.setItem(intentKey,JSON.stringify(request));setIntent(request);setIntentError('');}catch{setIntentError('无法保存重试凭据；尚未发出请求。请检查浏览器存储。');return false;}return dispatch(request,message);};
 const locate=n=>{setCursor(n);const el=viewport.current;if(el)el.scrollTo({left:Math.max(0,projection.timeToX(n)+64-el.clientWidth/2),behavior:'smooth'});};
 const close=()=>setPanel(null);
 const place=async(card,p)=>{const ok=await mutate({type:'storyAxis.place',id:card.id,expectedRevision:card.revision,...p},'已安排故事时间；叙述位置、大纲与画布保持原样。');if(ok&&alive.current){setCursor(p.start);requestAnimationFrame(()=>{const el=viewport.current,projection=latest.current?.projection;if(el&&projection)el.scrollLeft=Math.max(0,projection.timeToX(p.start)+64-el.clientWidth/2);});}return ok;};
 const unplace=card=>mutate({type:'storyAxis.unplace',id:card.id,expectedRevision:card.revision},'已移回待安排，仅清除故事时间。');
 const begin=(e,card)=>{if(editor||unavailable||locked.current||e.button!==0||e.target.closest('button'))return;dragged.current=false;gesture.current={pointerId:e.pointerId,x:e.clientX,y:e.clientY,scroll:viewport.current.scrollLeft,scrollY:viewport.current.scrollTop,card,moved:false};};
 const move=e=>{const g=gesture.current;if(!g||g.pointerId!==e.pointerId)return;if(!g.moved&&Math.hypot(e.clientX-g.x,e.clientY-g.y)<7)return;g.moved=true;dragged.current=true;e.preventDefault();e.currentTarget.setPointerCapture?.(e.pointerId);const el=viewport.current;if(!g.card){el.scrollLeft=g.scroll-(e.clientX-g.x);return;}const r=el.getBoundingClientRect();if(e.clientX>r.right-24)el.scrollLeft+=12;else if(e.clientX<r.left+24)el.scrollLeft-=12;const candidate=storyDragDrop(projection,{...r,left:r.left,right:r.right,top:r.top-el.scrollTop},el.scrollLeft,e.clientX,e.clientY,layout,g);setDrag({id:g.card.id,candidate});};
 const end=async e=>{const g=gesture.current;if(!g||g.pointerId!==e.pointerId)return;gesture.current=null;setDrag(null);if(!g.moved||!g.card||unavailable||!alive.current)return;const el=viewport.current,r=el.getBoundingClientRect();if(e.clientY<r.top||e.clientY>r.bottom)return;const p=storyDragDrop(projection,{left:r.left,right:r.right,top:r.top-el.scrollTop},el.scrollLeft,e.clientX,e.clientY,layout,g);if(p)await place(g.card,{...p,trackId:g.card.time.story.trackId,...(g.card.time.story.trackSource?{trackSource:g.card.time.story.trackSource}:{}),end:p.start+(g.card.time.story.end-g.card.time.story.start)});};
 const modeButtons=<div className="sa-switch" aria-label="时间线坐标"><button disabled={!!editor} onClick={()=>{cancel();relationClock.setMode('narration');}}>叙述顺序</button><button aria-pressed="true">故事时间</button></div>;
 return <section className={`story-axis ${evolution?'sa-has-relations':''} ${editor?'sa-editing-view':''} ${evolution&&view==='relations'?'sa-relations-view':''}`}><style>{storyAxisStyle}</style><header className="sa-header">{modeButtons}{axis&&<div className="sa-actions"><button className="sa-create" disabled={unavailable||!!editor} onClick={()=>setPanel({kind:'create'})}><Icon name="plus"/>新建</button><button aria-label="故事时间更多操作" aria-haspopup="dialog" disabled={!!editor} onClick={()=>setPanel({kind:'more'})}><Icon name="more-horizontal"/></button></div>}</header>
 {intent&&<div className="u-notice" role="status">上次故事时间修改等待确认，已保留原请求，不会重复创建。<button disabled={unavailable} onClick={()=>dispatch(intent,'已确认上次故事时间修改。')}>核对结果</button></div>}{intentError&&<p role="alert">{intentError}</p>}
 {!axis?<div className="sa-gate"><div className="sa-gate-art" aria-hidden="true">· ─ ◇ ─ ·</div><h2>让故事，拥有自己的时间</h2><p>先确定第一章读者所在的时刻，再选择历法与刻度。<br/>这里的每一次挪动，都不会改变叙述顺序。</p><button className="u-primary" disabled={unavailable} onClick={()=>setPanel({kind:'setup'})}>设置故事坐标系 →</button><p className="sa-note">尚未设置，不会写入任何时间安排</p></div>:<>
 <div className="sa-context"><button className="sa-anchor-pill" onClick={()=>setPanel({kind:'setup'})}>◇ {axis.anchor.label} · {formatStoryDate(axis.anchor.coordinate,axis.calendar)} · {axis.calendar.name}</button><select className="sa-track-filter" aria-label="故事轨道筛选" value={trackFilter} onChange={e=>setTrackFilter(e.target.value)}><option value="all">全部轨道</option>{catalog.map(t=><option key={t.key} value={t.key}>{t.name}{t.trackSource==='shared'?'':' · 既有故事轨道'}</option>)}</select><div className="sa-navigation"><button aria-label="缩小故事时间" disabled={zoom<=-4} onClick={()=>setZoom(z=>clamp(z-1,-4,zoomLevels.daily))}>−</button><select className="sa-zoom-preset" aria-label="故事轴查看尺度" value={zoomPreset} onChange={e=>setZoom(zoomLevels[e.target.value])}><option value="overview">全景</option><option value="detail">细看</option><option value="daily">逐日</option></select><button aria-label="放大故事时间" disabled={zoom>=zoomLevels.daily} onClick={()=>setZoom(z=>clamp(z+1,-4,zoomLevels.daily))}>＋</button><button onClick={()=>locate(axis.anchor.coordinate)}>回到锚点</button></div></div>
 {evolution&&<nav className="sa-switch sa-content-switch" aria-label="故事时间内容"><button aria-pressed={view==='axis'} onClick={()=>setView('axis')}>故事轴</button><button aria-pressed={view==='relations'} onClick={()=>setView('relations')}>关系演变</button></nav>}
 <p className="sa-note">{axis.primaryTick.step}{({year:'年',month:'月',day:'天'})[axis.primaryTick.unit]}一个主刻度 · 可精确到任意一天 · 空白年代自动折叠</p>
 <div className={`sa-workspace ${editor?'sa-editing':''}`}><section className="sa-axis-column" aria-label="故事轴与待安排"><div ref={viewport} className="sa-viewport" onPointerDown={e=>{if(e.target.closest('button,[data-story-card]'))return;begin(e,null);}} onPointerMove={move} onPointerUp={end} onPointerCancel={cancel} onLostPointerCapture={()=>{if(gesture.current)cancel();}}><div className="sa-world" style={{width:projection.width+320,height:layout.height}}>
 <div className="sa-line" style={{top:layout.line}}/><div className="sa-axis-hit" onClick={e=>{if(!dragged.current){const r=viewport.current.getBoundingClientRect();setCursor(projection.xToTime(e.clientX-r.left+viewport.current.scrollLeft-64));}}} style={{top:layout.line-20}} onDoubleClick={e=>{if(!dragged.current){const r=viewport.current.getBoundingClientRect();setPanel({kind:'marker',coordinate:projection.xToTime(e.clientX-r.left+viewport.current.scrollLeft-64)});}}} onContextMenu={e=>{e.preventDefault();cancel();const r=viewport.current.getBoundingClientRect();setPanel({kind:'marker',coordinate:projection.xToTime(e.clientX-r.left+viewport.current.scrollLeft-64)});}}/>
 {ticks.map(t=><div className="sa-tick" key={t.coordinate} style={{left:t.x+64,top:layout.line-3}}><span title={formatStoryDate(t.coordinate,axis.calendar)}>{storyTickLabel(axis,t.coordinate,zoom)}</span></div>)}
 {projection.segments.filter(s=>s.folded).map(s=><div className="sa-break" key={s.start} style={{left:s.x+s.width/2+64,top:layout.line-21}} title={`${formatStoryDate(s.start,axis.calendar)} — ${formatStoryDate(s.end,axis.calendar)} · ${(s.end-s.start).toLocaleString()} 天`}><b>〰</b><br/>{storyGapLabel(axis,s.start,s.end)}</div>)}
 <button className="sa-origin" style={{left:projection.timeToX(axis.anchor.coordinate)+64,top:layout.line-43}} onClick={()=>setPanel({kind:'marker',coordinate:axis.anchor.coordinate})}>◇ 第一章 · ＋</button>
 {cursor!==axis.anchor.coordinate&&<button className="sa-origin" aria-label="在当前故事位置添加标记" style={{left:projection.timeToX(cursor)+64,top:layout.line-18}} onClick={()=>setPanel({kind:'marker',coordinate:cursor})}>＋</button>}
 {layout.lanes.map(lane=><div key={lane.id} className="sa-lane" style={{top:lane.y,height:lane.height,'--lane-color':'var(--cg-muted)'}} data-story-space={lane.side}>{displayCards.filter(c=>c.displaySide===lane.side).map(card=>{const t=card.time.story,y=26+(card.displayRow??Math.min(30,t.row||0))*storyCardRowHeight;return <article {...planningCardPresentation(card,foreshadowIds)} key={card.id} tabIndex={0} role="button" data-story-card={card.id} className={`sa-card ${lane.side} ${drag?.id===card.id?'dragging':''} ${selected===card.id?'selected':''}`} style={{left:projection.timeToX(t.start)+64,top:y,'--stem':Math.max(12,lane.side==='above'?layout.line-(lane.y+y+storyCardHeight):lane.y+y-layout.line)+'px'}} onPointerDown={e=>begin(e,card)} title={`${planningCardPresentation(card,foreshadowIds).title} · ${formatStoryDate(t.start,axis.calendar)}`} aria-label={planningCardPresentation(card,foreshadowIds).title} onClick={()=>{if(!dragged.current){setSelected(card.id);setCursor(t.start);open(card);}}} onContextMenu={e=>{e.preventDefault();e.stopPropagation();cancel();setSelected(card.id);setCursor(t.start);open(card);}} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setSelected(card.id);setCursor(t.start);open(card);}}}><h3>{card.title}</h3></article>;})}</div>)}
 {markers.map(m=><button key={m.id} className="sa-marker" style={{left:projection.timeToX(m.coordinate)+64,top:layout.line+37+m.displayRow*34}} title={formatStoryDate(m.coordinate,axis.calendar)} onClick={()=>setPanel({kind:'marker',marker:m,coordinate:m.coordinate})}>{m.label}</button>)}
 {!placed.length&&!axis.markers.length&&<div className="sa-empty"><h3>从一个时刻开始</h3><p>点击轴后按 ＋，或右键添加标记，也可以从“＋ 标记”开始。把已有剧情卡放到轴的上方或下方，上下只表示摆放位置，含义由你决定。</p></div>}
 </div>{drag&&<div className="sa-drag-hint">{drag.candidate?`${formatStoryDate(drag.candidate.start,axis.calendar)} · 松手安排`:'移到轴上或轴下轨道；Esc 取消'}</div>}</div>
 <details className="sa-tray"><summary>待安排 <strong>{pending.length}</strong> · 共用剧情卡，不复制内容</summary><div className="sa-tray-grid">{pending.map(card=><article {...planningCardPresentation(card,foreshadowIds)} className="sa-tray-item" key={card.id} role="button" tabIndex={0} onClick={e=>{if(!e.target.closest('button'))open(card);}} onKeyDown={e=>{if(e.key==='Enter'&&e.target===e.currentTarget)open(card);}}><strong>{card.title}{card.time?.story&&<small className="sa-legacy">旧坐标待换算：{card.time.story.start} — {card.time.story.end}</small>}</strong><div><button disabled={unavailable} onClick={()=>setPanel({kind:'placement',card})}>安排时间</button></div></article>)}{!pending.length&&<p className="sa-note">所有剧情卡都已安排。移回待安排不会删除内容。</p>}</div></details></section>{evolution&&<div className="sa-relations-region" role="region" aria-label="故事关系内容" tabIndex={0}><TimelineRelations {...{call,novelId,state,sources,people,relations,selected,save,unavailable,onMemory}} projection={projection} mode="story" origin={0} count={1} cursor={cursor} pointLabel={formatStoryDate(cursor,axis.calendar)} changeCursor={n=>{setCursor(n);}} onCard={open} initialPair={relationTarget?.pair?pair(...relationTarget.pair):null}/></div>}{editor&&<div className="u-timeline-editor-region">{editor}</div>}</div>
 </>}
 {panel?.kind==='setup'&&<StoryAxisSetup {...{axis,busy:unavailable,close}} chapters={sources.chapters} onSave={value=>mutate({type:'storyAxis.configure',value},'故事坐标系已保存。')}/>}
 {axis&&panel?.kind==='marker'&&<StoryMarkerEditor key={panel.marker?.id||`new-${panel.coordinate}`} marker={panel.marker} coordinate={panel.coordinate} {...{axis,close}} busy={unavailable} onSave={async value=>{const ok=await mutate({type:panel.marker?'storyAxis.marker.update':'storyAxis.marker.create',...(panel.marker?{id:panel.marker.id}:{}),...value},'已保存时间标记；名称不会自动换算成日期。');if(ok)focusCoordinate(value.coordinate);return ok;}} onDelete={panel.marker?()=>mutate({type:'storyAxis.marker.delete',id:panel.marker.id}):undefined} onInsert={(marker,direction)=>setPanel({kind:'marker',coordinate:marker.coordinate+(direction==='before'?-1:1)})}/>}
 {axis&&panel?.kind==='placement'&&<StoryPlacementEditor sharedTracks={state.tracks} {...{axis,close}} card={panel.card} busy={unavailable} onSave={p=>place(panel.card,p)} onUnplace={()=>unplace(panel.card)}/>}
 {axis&&panel?.kind==='track'&&<StoryTrackEditor {...{axis,close}} track={panel.track} busy={unavailable} onSave={value=>mutate({type:panel.track?(panel.track.trackSource==='shared'?'track.update':'storyAxis.track.update'):'track.create',...(panel.track?{id:panel.track.id,...(panel.track.trackSource==='shared'?{}:{side:panel.track.side})}:{}),...value})} onDelete={panel.track&&panel.track.trackSource!=='shared'?()=>mutate({type:'storyAxis.track.delete',id:panel.track.id}):undefined}/>}
 {panel?.kind==='reference'&&<Modal title="引用已有剧情卡" close={close}><div className="u-form sa-reference"><p>同一套内容，独立的故事时间位置。不会复制卡片。</p><input aria-label="搜索已有剧情卡" placeholder="搜索剧情卡" value={query} onChange={e=>setQuery(e.target.value)}/>{cards.filter(c=>c.title.includes(query)).map(c=><button key={c.id} onClick={()=>setPanel({kind:'placement',card:c})}><span>{c.title}</span><small>{c.time?.story?.axisVersion===1?'修改时间':'安排时间'} →</small></button>)}{!cards.length&&<p>还没有剧情卡，可以先新建一张。</p>}<button onClick={()=>{close();onCreate();}}>＋ 新建剧情卡</button></div></Modal>}
 {panel?.kind==='create'&&<Modal title="新建与添加" close={close}><div className="u-form sa-more"><button onClick={()=>{close();onCreate();}}><Icon name="plus"/><span>新建剧情卡<small>创建共用内容，之后自由安排时间</small></span></button><button onClick={()=>setPanel({kind:'reference'})}><Icon name="folder"/><span>引用已有剧情卡<small>不复制内容，只安排故事位置</small></span></button><button onClick={()=>setPanel({kind:'marker',coordinate:cursor})}><Icon name="flag"/><span>添加时间标记<small>名称自由，位置由你指定</small></span></button></div></Modal>}
 {panel?.kind==='more'&&<Modal title="故事时间" close={close}><div className="u-form sa-more"><button onClick={()=>setPanel({kind:'track'})}><Icon name="route"/><span>添加轨道<small>与叙述时间线共用名称和颜色</small></span></button><button onClick={()=>setPanel({kind:'setup'})}><Icon name="settings"/><span>时间坐标设置<small>历法、锚点与刻度</small></span></button><button onClick={()=>{close();onMore();}}><Icon name="history"/><span>备份、历史与恢复</span></button><small>轨道名称和颜色共用；故事日期和卡片摆放独立，不改变叙述顺序。</small><div className="sa-track-list">{catalog.map(t=><button key={t.key} onClick={()=>setPanel({kind:'track',track:t})}>{t.name}<small>{t.trackSource==='shared'?'共享轨道':'既有故事轨道'} · 设置</small></button>)}</div></div></Modal>}
 </section>;
}
